', 'G3', 'A3', 'Bb3', 'C4', 'D4', 'C4', 'Bb3', 'A3', 'G3', 'F3', 'E3', 'D3']); flash('d-min-kb');" aria-label="Play D minor scale pitches" title="play D minor scale up and down" class="play-btn pale-bg rounded-full shadow-md cursor-pointer button p-4"><img width="28" height="28" alt="" src="/images/play.svg"></button></div><ul id="d-min-kb" class="keyboard flex justify-center" x-data=""><li class="white c"></li><li class="black cs"></li><li class="white d touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('D3');" @mouseup="releaseNoteOrChord('D3')" @touchstart.prevent="triggerNoteOrChord('D3');" @touchend.prevent="releaseNoteOrChord('D3')"><span>D</span></li><li class="black ds"></li><li class="white e touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('E3');" @mouseup="releaseNoteOrChord('E3')" @touchstart.prevent="triggerNoteOrChord('E3');" @touchend.prevent="releaseNoteOrChord('E3')"><span>E</span></li><li class="white f touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('F3');" @mouseup="releaseNoteOrChord('F3')" @touchstart.prevent="triggerNoteOrChord('F3');" @touchend.prevent="releaseNoteOrChord('F3')"><span>F</span></li><li class="black fs"></li><li class="white g touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('G3');" @mouseup="releaseNoteOrChord('G3')" @touchstart.prevent="triggerNoteOrChord('G3');" @touchend.prevent="releaseNoteOrChord('G3')"><span>G</span></li><li class="black gs"></li><li class="white a touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('A3');" @mouseup="releaseNoteOrChord('A3')" @touchstart.prevent="triggerNoteOrChord('A3');" @touchend.prevent="releaseNoteOrChord('A3')"><span>A</span></li><li class="black as touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('Bb3');" @mouseup="releaseNoteOrChord('Bb3')" @touchstart.prevent="triggerNoteOrChord('Bb3');" @touchend.prevent="releaseNoteOrChord('Bb3')"><span>B<sub>♭</sub></span></li>